import{_ as o,o as a,c as i,a2 as c}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse(`{"title":"ADR-0059 — Pulizia della cartella di configurazione legacy .memobrain/ dopo l'aggiornamento e ZIP coerente (M21, Onda D)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0059-pulizia-cartella-configurazione-legacy-e-zip-coerente.md","filePath":"adr/0059-pulizia-cartella-configurazione-legacy-e-zip-coerente.md"}`),n={name:"adr/0059-pulizia-cartella-configurazione-legacy-e-zip-coerente.md"};function l(t,e,r,s,d,u){return a(),i("div",null,[...e[0]||(e[0]=[c('<h1 id="adr-0059-—-pulizia-della-cartella-di-configurazione-legacy-memobrain-dopo-l-aggiornamento-e-zip-coerente-m21-onda-d" tabindex="-1">ADR-0059 — Pulizia della cartella di configurazione legacy <code>.memobrain/</code> dopo l&#39;aggiornamento e ZIP coerente (M21, Onda D) <a class="header-anchor" href="#adr-0059-—-pulizia-della-cartella-di-configurazione-legacy-memobrain-dopo-l-aggiornamento-e-zip-coerente-m21-onda-d" aria-label="Permalink to &quot;ADR-0059 — Pulizia della cartella di configurazione legacy `.memobrain/` dopo l&#39;aggiornamento e ZIP coerente (M21, Onda D)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-16, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.7 (2026-11-16); implementata e rilasciata con la 1.7.2. Emenda <a href="./0052-rebrand-clarae-notanda.html">ADR-0052</a> (la fase 1 «mai cancellazioni»)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.7 (2026-11-16): §2.8.2, §3.4.6 («Pulizia della cartella legacy»), §3.5.2 e Appendice C.4</td></tr><tr><td><strong>Data</strong></td><td>2026-11-15</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.4.6 (scope di sincronizzazione della cartella di configurazione, <code>Specifications.md:1208</code>); §3.4.5 e D-04 (nessuna perdita silenziosa: le versioni scartate restano nello storico); §2.8.2 (Download ZIP «con i path originali, escluse le parti specifiche del dispositivo», <code>:670</code>); §3.5.2 (<code>export.zip</code> e job di export, <code>:1286-1289</code>); ADR-0010 (impostazioni sincronizzate); ADR-0052 (rebrand: punto 2.2, cartella del vault «in due fasi»)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>sì, in un punto:</strong> §2.8.2 e §3.5.2 dicono che lo ZIP ha i path originali; qui i path <code>.memobrain/…</code> diventano <code>.clarae/…</code> (e la cartella di configurazione, oltre a ciò che lo spec già esclude, non si presenta più con due nomi). Per il resto <strong>emenda ADR-0052</strong>, che alla fase 1 dice «mai cancellazioni» e che lasciava la cartella vecchia «per sempre» quando c&#39;era una collisione. Lo spec v1.6 dice ancora <code>.memobrain/</code> in §3.4.6: l&#39;aggiornamento di quella sezione è dovuto per ADR-0052 (accettata il 2026-11-16, recepita nella stessa v1.7) e non cambia per questo ADR. Da recepire nello spec v1.7 (<a href="./../spec-v1.7-proposta.html"><code>spec-v1.7-proposta.md</code></a>): §2.8.2 e §3.5.2 (path dello ZIP)</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (prove: unit di <code>apps/desktop/internal/vaultdir/cleanup_test.go</code> su collisioni, snapshot, vault collegato, link simbolici, marcatore per versione; unit di <code>internal/sync/configmigrate_test.go</code> sul delete della riga legacy e di <code>internal/vault/config_shadowed_test.go</code> sulla rimozione del file; QA manuale su un vault reale) · workbench web (il core compilato in WASM include gli stessi pacchetti <code>vaultdir</code> e <code>sync</code>, e i loro test girano sotto Node con <code>task test-wasm</code>; un vault del browser nato dalla 1.x può avere la cartella vecchia; nessuna voce nuova del registro di parità) · console (nessuna modifica di interfaccia; lo ZIP di un vault privato è prodotto nel browser) · cloud (<code>services/cloud/internal/export/service.go</code> <code>writeZip</code>; prove: <code>service_test.go</code> dell&#39;export e <code>services/cloud/test/integration/export_test.go</code>, <code>task test-integration</code>). Lo ZIP privato: vitest di <code>packages/vaultcrypto-web</code> (<code>configdir.test.ts</code>, <code>export.test.ts</code>). Prova <code>task lint-brand</code> per le righe nuove dell&#39;allowlist</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Su E2BR i vault hanno <strong>due cartelle di configurazione</strong>, <code>.clarae/</code> e <code>.memobrain/</code>, e lo ZIP scaricato dal cloud contiene la seconda. Le cause sono quattro, tutte nel codice:</p><ul><li><strong>Locale.</strong> <code>vaultdir.Ensure</code> (<code>apps/desktop/internal/vaultdir/vaultdir.go</code>) sposta la parte locale (<code>index.db*</code>, <code>sync.db*</code>, <code>cache/</code>, <code>snapshots/</code>, <code>workspace*.json</code>) da <code>.memobrain/</code> a <code>.clarae/</code> alla prima apertura. Quando una voce esiste in <strong>entrambe</strong>, vince <code>.clarae/</code> e la copia legacy resta dov&#39;è, «mai cancellata» (commento del pacchetto e ADR-0052, fase 1): resta così per sempre.</li><li><strong>Sync.</strong> Le impostazioni sincronizzate di un vault collegato si spostano solo con <code>features.config_dir_v2</code>. Il motore salta il file se <code>.clarae/&lt;nome&gt;</code> esiste già (<code>sync/configmigrate.go</code>, <code>configMoveTarget</code>) e lascia viva sul server la riga <code>.memobrain/&lt;nome&gt;</code>.</li><li><strong>Il flag spento rimette tutto indietro.</strong> Con <code>config_dir_v2</code> spento il vault riporta le impostazioni nella cartella vecchia (<code>vault.FS.ShelveConfig</code>, <code>vault/config.go:280</code>) e le legge da entrambe (<code>ReadConfig</code>, <code>:128</code>). <strong>Un cloud 1.5 o 1.6 distribuisce <code>false</code></strong>, uno 1.7 <code>true</code> (<code>docs/admin-guide/profili-quote-audit.md</code>, riga di <code>features.config_dir_v2</code>). E2BR esegue la 1.5.1: finché non passa a una versione con questo ADR i vault restano o tornano in <code>.memobrain/</code>.</li><li><strong>Lo ZIP.</strong> <code>writeZip</code> (<code>services/cloud/internal/export/service.go</code>) scrive i path del server così come sono, esclusi quelli che <code>pathrules.IsExcluded</code> scarta; l&#39;export di un vault <strong>privato</strong> (nel browser, in <code>packages/vaultcrypto-web/src/export.ts</code>) scrive i path decifrati e salta un secondo file con lo stesso path (<code>duplicate_path</code>).</li></ul><p>ADR-0052 aveva scelto di non cancellare nulla: un dato perso per un nome sbagliato era peggio di una cartella in più. Con la 1.7 il doppio nome non ha più ragioni dove il cloud è aggiornato, e la cartella in più confonde (due fonti per le stesse impostazioni, un ZIP con la cartella del vecchio nome).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="pulizia-locale-dopo-l-aggiornamento" tabindex="-1">Pulizia locale dopo l&#39;aggiornamento <a class="header-anchor" href="#pulizia-locale-dopo-l-aggiornamento" aria-label="Permalink to &quot;Pulizia locale dopo l&#39;aggiornamento&quot;">​</a></h3><ol><li><strong><code>vaultdir.CleanupLegacy</code></strong>, eseguita all&#39;apertura del vault <strong>dopo</strong> <code>Ensure</code>. Un <strong>marcatore locale</strong>, il file <code>.clarae/cache/legacy-config-cleanup</code> (escluso dalla sync perché sta in <code>cache/</code>), contiene la versione dell&#39;app (<code>Options.Version</code>): la pulizia gira <strong>una volta per versione</strong>. Se non esiste nessuna cartella legacy, non scrive nulla.</li><li>Per ogni voce di <code>.memobrain/</code> (tutto ciò che non è elencato qui non si tocca): <ul><li><strong>voci solo locali</strong> (<code>index.db*</code>, <code>sync.db*</code>, <code>workspace*.json</code>, <code>cache/</code>) che <code>.clarae/</code> ha già: cancellate. Per <code>sync.db*</code> solo quando il <code>sync.db</code> aperto è quello di <code>.clarae/</code>; con un database aperto altrove non si cancella nulla;</li><li><strong><code>snapshots/</code></strong>: le voci senza collisione si spostano in <code>.clarae/snapshots/</code>; quelle <strong>identiche</strong> a una già presente si cancellano; quelle <strong>diverse</strong> con lo stesso nome restano dove sono (sono l&#39;unica copia di quella versione);</li><li><strong>impostazioni sincronizzabili di un vault non collegato, in collisione</strong>: <strong>identiche</strong> alla copia in <code>.clarae/</code> si cancellano; <strong>diverse</strong>, la copia legacy va nel <strong>cestino del vault</strong> (<code>vault.FS.Trash</code>, passato come <code>CleanupOptions.Trash</code>, che conserva il percorso) e non si cancella;</li><li><strong>file spazzatura del sistema</strong> (<code>.DS_Store</code>, <code>Thumbs.db</code>, <code>desktop.ini</code>): si cancellano;</li><li><strong>cartelle svuotate dalla pulizia</strong> e <strong><code>.memobrain/</code> vuota</strong>: si rimuovono (<code>os.Remove</code>, che rifiuta una cartella non vuota).</li></ul></li><li><strong>Ciò che non si tocca:</strong> il vault collegato con impostazioni sincronizzate ancora in <code>.memobrain/</code> (<code>Options.Linked</code>: le gestisce la sync, punto 4), una voce locale senza la sua gemella in <code>.clarae/</code> (lo spostamento non è avvenuto: non spetta alla pulizia), qualunque cosa che non sia nell&#39;elenco, i link simbolici (non si entra né si rimuovono) e un file o una cartella con quel nome al posto della cartella legacy. L&#39;app la esegue in <code>doOpenVault</code>, subito dopo <code>Ensure</code> e <code>AdoptSettings</code>, con <code>Linked</code> calcolato all&#39;apertura; un errore si scrive nel log e non impedisce di aprire il vault.</li></ol><h3 id="pulizia-sincronizzata" tabindex="-1">Pulizia sincronizzata <a class="header-anchor" href="#pulizia-sincronizzata" aria-label="Permalink to &quot;Pulizia sincronizzata&quot;">​</a></h3><ol start="4"><li><strong><code>sync/configmigrate.go</code></strong> (<code>dropShadowedConfig</code>). Quando <code>.clarae/&lt;nome&gt;</code> esiste già e <strong>entrambe</strong> le righe sono <strong>pulite</strong> (sincronizzate, senza modifiche locali, tentativi, errori o conflitti; <code>cleanSyncedRow</code>), il file corrente su disco ha ancora l&#39;hash noto a <code>sync.db</code> e nessuna delle due è in attesa di una decisione, il motore toglie il file legacy dal disco (<code>vault.FS.RemoveShadowedConfig</code>: <strong>cancellato</strong> se identico a quello corrente, <strong>nel cestino del vault</strong> <code>.trash/</code> se diverso; un file cambiato dopo l&#39;ultima scansione non si tocca) e segna la riga come cancellazione locale, che il push invia come <strong>operazione di cancellazione con <code>base_rev</code></strong>. La revisione resta nello storico del cloud, quindi <strong>nessuna perdita silenziosa</strong> (D-04). Si fanno al massimo 64 file per passata, insieme agli spostamenti. Vale solo con <code>config_dir_v2</code> acceso, cioè contro un <strong>cloud ≥ 1.7</strong>: un cloud 1.5 o 1.6 distribuisce <code>false</code>, il motore non sposta né pulisce nulla, e la correzione non ha effetto.</li><li>La cancellazione non si fa se <code>.clarae/&lt;nome&gt;</code> non esiste (lo spostamento è un&#39;altra strada, già prevista) né per una riga con conflitti o con modifiche locali, e il motore riprova alla passata successiva.</li></ol><h3 id="zip-coerente" tabindex="-1">ZIP coerente <a class="header-anchor" href="#zip-coerente" aria-label="Permalink to &quot;ZIP coerente&quot;">​</a></h3><ol start="6"><li><strong>Server (<code>writeZip</code>) e browser (<code>packages/vaultcrypto-web/src/export.ts</code>):</strong> i path <code>.memobrain/…</code> si riscrivono in <code>.clarae/…</code>: sul server con <code>archivePath</code> in <code>services/cloud/internal/export/service.go</code> (che usa <code>pathrules.ConfigRel</code>), nel browser con <code>archivePath</code> in <code>packages/vaultcrypto-web/src/configdir.ts</code> (la stessa regola; <code>configdir.test.ts</code> confronta i nomi con quelli generati da Go in <code>platform/vaultPaths.gen.ts</code>). <strong>In caso di collisione vince <code>.clarae/</code></strong>: la voce <code>.memobrain/</code> con lo stesso nome non entra nell&#39;archivio, <strong>qualunque sia l&#39;ordine</strong> nel manifest (l&#39;export privato la riconosce prima di scaricare i blob e non la scarica; nel rapporto compare come <code>duplicate_path</code>). Le esclusioni di <code>IsExcluded</code> restano.</li><li><strong>Allowlist del rebrand.</strong> Le occorrenze nuove di <code>.memobrain</code> nel codice entrano in <code>scripts/rebrand/allowlist.tsv</code> come righe di classe <code>legacy</code>, con la release di rimozione <strong>2.0</strong> nel motivo: una riga nuova, per <code>packages/vaultcrypto-web/src/configdir.ts</code>. Il codice Go usa <code>pathrules.LegacyConfigDirs</code> e non cita il nome. <code>task lint-brand</code> boccia ogni altra occorrenza e ogni riga che non copre più nulla.</li></ol><h3 id="prove" tabindex="-1">Prove <a class="header-anchor" href="#prove" aria-label="Permalink to &quot;Prove&quot;">​</a></h3><ul><li>Unit di <code>vaultdir</code>: collisioni, snapshot, <code>sync.db</code> aperto altrove mai toccato, marcatore per versione (due aperture, una pulizia; versione nuova, pulizia nuova), cestino per un vault non collegato, vault collegato, link simbolici.</li><li>Unit di <code>sync/configmigrate</code> e di <code>vault</code> (<code>RemoveShadowedConfig</code>): delete della riga legacy pulita; nessun delete con modifiche locali, conflitto o <code>.clarae/&lt;nome&gt;</code> assente; nessuna azione con il flag spento.</li><li>Export del server: ZIP con cartella legacy e collisione (vince <code>.clarae/</code>), senza collisione (riscritto), con le esclusioni.</li><li>vitest dell&#39;export privato: riscrittura e precedenza di <code>.clarae/</code>.</li><li><code>task lint-brand</code>; <code>task test-wasm</code> per il core.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Non cancellare mai (ADR-0052 com&#39;è)</strong> — scartata: lascia la cartella in più per sempre e due fonti per le stesse impostazioni; l&#39;owner lo ha segnalato come difetto.</li><li><strong>Cancellare tutto <code>.memobrain/</code> all&#39;aggiornamento</strong> — scartata: perde ciò che c&#39;è solo lì (un vault condiviso con un dispositivo 1.4, impostazioni di un vault non collegato che non esistono in <code>.clarae/</code>, snapshot senza copia).</li><li><strong>Cancellare sempre la copia legacy in collisione anche per le impostazioni di un vault non collegato</strong> — scartata: la copia può contenere modifiche che <code>.clarae/</code> non ha; va nel cestino, dove l&#39;utente la ritrova.</li><li><strong>Pulire la riga legacy sul server con un job del cloud</strong> — scartata: il server non conosce il significato delle cartelle (il merge e le regole di path vivono sul client, §3.4.1) e un job non preserverebbe la regola «solo se <code>.clarae/</code> ha già il file».</li><li><strong>Lo ZIP con i path originali (spec com&#39;è)</strong> — scartata: un vault scaricato con la cartella del vecchio nome non si apre con le impostazioni nelle app che oggi si aspettano <code>.clarae/</code>, e contiene due copie quando il vault è passato per entrambe.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Dopo l&#39;aggiornamento e un cloud ≥ 1.7 i vault perdono la cartella <code>.memobrain/</code>; lo ZIP ha solo <code>.clarae/</code>.</li><li><strong>Limite:</strong> con un cloud 1.5 o 1.6 (E2BR prima dell&#39;aggiornamento) la parte sincronizzata non si corregge, perché <code>config_dir_v2</code> arriva <code>false</code> e <code>ShelveConfig</code> riporta le impostazioni in <code>.memobrain/</code>: <strong>serve un cloud ≥ 1.7</strong>; l&#39;aggiornamento di E2BR va fatto con la procedura dell&#39;Onda F. La pulizia <strong>locale</strong> della parte non sincronizzata invece parte con il client, anche contro un cloud vecchio, ma solo per le voci che <code>.clarae/</code> ha già; e per i vault collegati le impostazioni sincronizzate restano alla sync. Il marcatore per versione fa girare la pulizia una volta per versione dell&#39;app: un client che la esegue prima dell&#39;aggiornamento del cloud la rifà alla versione successiva.</li><li><strong>Un dispositivo 1.4 o precedente</strong> rimasto su un vault dopo la pulizia ricrea le impostazioni che non trova nella cartella vecchia: due copie con id diversi, da riconciliare a mano. È il rischio già descritto in ADR-0052 e in <code>docs/admin-guide/migrazione-clarae.md</code>; la pulizia lo rende più probabile finché il vault ha dispositivi vecchi, quindi la sequenza di aggiornamento è invariata: prima ogni dispositivo, poi il cloud.</li><li><strong>Si perde l&#39;immutabilità di <code>.memobrain/</code></strong> promessa da ADR-0052 («mai cancellazioni»): la pulizia cancella solo ciò che <code>.clarae/</code> ha già (stessa identità di nome) o che è un duplicato; il resto va nel cestino. Nessun dato che esiste in una sola copia viene eliminato.</li><li><strong>Il cloud ≥ 1.7 conserva</strong> nello storico la revisione della riga legacy cancellata (visibile come file cancellato di quel vault): è lo scopo di D-04.</li><li><strong>Da rivedere con la 2.0</strong>, quando il doppio nome si toglie (<code>pathrules.LegacyConfigDirs</code>): le righe <code>legacy</code> dell&#39;allowlist e <code>CleanupLegacy</code> si eliminano insieme.</li><li><strong>Spec da aggiornare (v1.7):</strong> §2.8.2 e §3.5.2 (path dello ZIP); §3.4.6 si riallinea con il recepimento di ADR-0052.</li></ul>',19)])])}const m=o(n,[["render",l]]);export{p as __pageData,m as default};
